private void checkMistFormTrigger() {
        long gameTime = this.level().getGameTime();
        if (gameTime < this.mistCooldownUntil) return;
        this.recentDamage.removeIf(p -> gameTime - p.getFirst() > 100);
        float total = 0;
        for (Pair<Long, Float> p : this.recentDamage) {
            total += p.getSecond();
        }
        if (total > this.getMaxHealth() * 0.2f) {
            this.setState(DraculaState.MIST);
            this.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
            this.mistStartTime = gameTime;
            this.mistCooldownUntil = gameTime + MIST_COOLDOWN;
            this.recentDamage.clear();
        }
    }

@Override
    protected void actuallyHurt(ServerLevel level, DamageSource damageSource, float amount) {
        DraculaState state = this.getState();
        if (damageSource.is(DamageTypeTags.IS_PROJECTILE)) {
            if (state == DraculaState.RANGED) {
                amount *= 0.5f;
            } else if (state == DraculaState.RAGED) {
                if (damageSource.getDirectEntity() instanceof AbstractArrow) {
                    amount *= 1.5f;
                }
            }
        }
        super.actuallyHurt(level, damageSource, amount);
        if (damageSource.getEntity() instanceof ServerPlayer player) {
            addPlayerToEvent(player);
        }
        if (getState() == DraculaState.DEFAULT) {
            setState(DraculaState.PASSIVE);
        }

        if (this.getState() == DraculaState.PASSIVE && damageSource.getEntity() instanceof LivingEntity attacker) {
            double d0 = attacker.getX() - this.getX();
            double d1 = attacker.getZ() - this.getZ();
            attacker.knockback(0.5D, d0, d1);
        }

        if (this.getState() == DraculaState.RAGED) {
            this.recentDamage.add(Pair.of(level.getGameTime(), amount));
            this.checkMistFormTrigger();
        }
        updateEvent();
    }

private void tickMistForm() {
        if (this.level().isClientSide()) return;
        if (this.mistStartTime == -1) this.mistStartTime = this.level().getGameTime();
        if (this.level().getGameTime() - this.mistStartTime > MIST_DURATION) {
            this.setState(DraculaState.RAGED);
            this.mistStartTime = -1;
            return;
        }

    }

@Override
    public void tick() {
        super.tick();
        tickTransformation();
        if (this.getState() == DraculaState.MIST) {
            tickMistForm();
        }
        if (!this.level().isClientSide() && this.isAlive()) {
            // invulnerability also changes through mist form ending and brain memories (flying sword/needle), so sync every tick. Only changed values are sent.
            updateEvent();
        }
    }

public void fulfilRequest() {
		if (!hasPendingRequest()) {
			return;
		}

		CorporeaSpark spark = CorporeaHelper.instance().getSparkForBlock(level, requestPos);
		if (spark != null) {
			BlockEntity te = spark.getSparkNode().getWorld().getBlockEntity(spark.getSparkNode().getPos());
			if (te instanceof CorporeaRequestor requestor) {
				requestor.doCorporeaRequest(request, requestCount, spark, null);

				forget();
				setChanged();
			}
		}
	}

public void remember(BlockPos pos, CorporeaRequestMatcher request, int count, int missing) {
		this.requestPos = pos;
		this.request = request;
		this.requestCount = retainMissing ? missing : count;

		setChanged();
	}

public void forget() {
		request = null;
		requestCount = 0;
	}

@Override
	public void readPacketNBT(CompoundTag cmp) {
		super.readPacketNBT(cmp);

		int x = cmp.getInt(TAG_REQUEST_X);
		int y = cmp.getInt(TAG_REQUEST_Y);
		int z = cmp.getInt(TAG_REQUEST_Z);
		requestPos = new BlockPos(x, y, z);

		ResourceLocation reqType = ResourceLocation.tryParse(cmp.getString(TAG_REQUEST_TYPE));
		if (reqType != null && corporeaMatcherDeserializers.containsKey(reqType)) {
			request = corporeaMatcherDeserializers.get(reqType).apply(cmp);
		} else {
			request = null;
		}
		requestCount = cmp.getInt(TAG_REQUEST_COUNT);
		retainMissing = cmp.getBoolean(TAG_RETAIN_MISSING);
	}

@Override
	public void writePacketNBT(CompoundTag cmp) {
		super.writePacketNBT(cmp);

		cmp.putInt(TAG_REQUEST_X, requestPos.getX());
		cmp.putInt(TAG_REQUEST_Y, requestPos.getY());
		cmp.putInt(TAG_REQUEST_Z, requestPos.getZ());

		ResourceLocation reqType = request != null ? corporeaMatcherSerializers.get(request.getClass()) : null;

		if (reqType != null) {
			cmp.putString(TAG_REQUEST_TYPE, reqType.toString());
			request.writeToNBT(cmp);
			cmp.putInt(TAG_REQUEST_COUNT, requestCount);
		}
		cmp.putBoolean(TAG_RETAIN_MISSING, retainMissing);
	}

@Override
	public void neighborChanged(BlockState state, Level world, BlockPos pos, Block fromBlock, BlockPos fromPos, boolean isMoving) {
		boolean power = false;
		for (var direction : Direction.values()) {
			var neighborPos = pos.relative(direction);
			var neighborState = world.getBlockState(neighborPos);
			if (!neighborState.is(BotaniaBlocks.corporeaInterceptor)) {
				if (world.getSignal(neighborPos, direction) > 0) {
					power = true;
					break;
				}
			}
		}
		boolean powered = state.getValue(BlockStateProperties.POWERED);

		if (power && !powered) {
			if (world.getBlockEntity(pos) instanceof CorporeaRetainerBlockEntity retainer) {
				retainer.fulfilRequest();
			}
			world.setBlockAndUpdate(pos, state.setValue(BlockStateProperties.POWERED, true));
		} else if (!power && powered) {
			world.setBlockAndUpdate(pos, state.setValue(BlockStateProperties.POWERED, false));
		}
	}

@Override
	public void interceptRequestLast(CorporeaRequestMatcher request, int count, CorporeaSpark spark, CorporeaSpark source, List<ItemStack> stacks, Set<CorporeaNode> nodes, boolean doit) {
		List<ItemStack> filter = getFilter();

		boolean filterMatch = false;
		for (ItemStack stack : filter) {
			if (request.test(stack)) {
				filterMatch = true;
			}
		}

		if (filterMatch || filter.isEmpty()) {
			int missing = count;
			for (ItemStack stack : stacks) {
				missing -= stack.getCount();
			}

			if (missing > 0 && !getBlockState().getValue(BlockStateProperties.POWERED)) {
				BlockPos requestorPos = source.getSparkNode().getPos();

				List<CorporeaRetainerBlockEntity> retainers = new ArrayList<>();
				for (Direction dir : Direction.values()) {
					BlockEntity tile = level.getBlockEntity(worldPosition.relative(dir));
					if (tile instanceof CorporeaRetainerBlockEntity retainer) {
						retainers.add(retainer);
						retainer.forget();
					}
				}

				level.setBlockAndUpdate(getBlockPos(), getBlockState().setValue(BlockStateProperties.POWERED, true));
				level.scheduleTick(getBlockPos(), getBlockState().getBlock(), 2);

				for (CorporeaRetainerBlockEntity retainer : retainers) {
					retainer.remember(requestorPos, request, count, missing);
				}
			}
		}
	}

private void updateTimes(Level level) {
		if (paused) {
			unpause(level);
			return;
		}

		if (isBurning(level)) {
			remainingBurnTime = getBurnTimeFinish() - level.getGameTime();
		} else {
			remainingBurnTime = 0;
		}
		if (isCooking()) {
			remainingCookTime = getCookTimeFinish() - level.getGameTime();
		} else {
			remainingCookTime = 0;
		}
	}

public boolean tick(Level level) {
		updateTimes(level);

		AtomicBoolean didSomething = new AtomicBoolean(true);
		if (isBurning(level) || readyToStartCooking()) {
			Optional<T> fr = getCookingRecipe();
			if (fr.isEmpty() && isCooking()) {
				setIsCooking(false);
			}
			fr.ifPresent(recipe -> {
				updateFuel(level, recipe);

				if (isBurning(level) && canSmelt(recipe, level)) {
					updateCookingProgress(level, recipe);
				} else if (!isBurning(level)) {
					didSomething.set(false);
				}
			});
		}

		if (!isBurning(level) && isCooking()) {
			updateCookingCooldown(level);
		} else {
			didSomething.set(false);
		}
		return didSomething.get();
	}

private void unpause(Level level) {
		paused = false;

		if (remainingBurnTime > 0) {
			setBurnTimeFinish(level.getGameTime() + remainingBurnTime);
		}
		if (remainingCookTime > 0) {
			setCookTimeFinish(level.getGameTime() + remainingCookTime);
			setIsCooking(true);
		}
	}

public void pause() {
		paused = true;
		setCookTimeFinish(0);
		setIsCooking(false);
		setBurnTimeFinish(0);
	}

private void updateCookingProgress(Level level, T cookingRecipe) {
		if (isCooking() && finishedCooking(level)) {
			smelt(cookingRecipe, level);
			if (canSmelt(cookingRecipe, level)) {
				setCookTime(level, (int) (cookingRecipe.getCookingTime() * (1 / cookingSpeedMultiplier)));
			} else {
				setIsCooking(false);
			}
		} else if (!isCooking()) {
			setIsCooking(true);
			setCookTime(level, (int) (cookingRecipe.getCookingTime() * (1 / cookingSpeedMultiplier)));
		}
	}

private boolean finishedCooking(Level level) {
		return getCookTimeFinish() <= level.getGameTime();
	}

private void smelt(Recipe<?> recipe, Level level) {
		if (!canSmelt(recipe, level)) {
			return;
		}

		ItemStack input = getCookInput();
		ItemStack recipeOutput = recipe.getResultItem(level.registryAccess());
		ItemStack output = getCookOutput();
		if (output.isEmpty()) {
			setCookOutput(recipeOutput.copy());
		} else if (output.getItem() == recipeOutput.getItem()) {
			output.grow(recipeOutput.getCount());
			setCookOutput(output);
		}

		if (input.getItem() == Blocks.WET_SPONGE.asItem() && !getFuel().isEmpty() && getFuel().getItem() == Items.BUCKET) {
			setFuel(new ItemStack(Items.WATER_BUCKET));
		}

		if (cookingRecipe != null) {
			incrementRecipeUsed(cookingRecipe.id());
			addStoredExperience(cookingRecipe.value().getExperience());
		}
		input.shrink(1);
		setCookInput(input);
	}

private void updateFuel(Level level, T cookingRecipe) {
		ItemStack fuel = getFuel();
		if (!isBurning(level) && canSmelt(cookingRecipe, level)) {
			if (getBurnTime(fuel, recipeType, burnTimeModifier) <= 0) {
				return;
			}
			setBurnTime(level, (int) (getBurnTime(fuel, recipeType, burnTimeModifier) * fuelEfficiencyMultiplier / cookingSpeedMultiplier));
			if (isBurning(level)) {
				if (fuel.hasCraftingRemainingItem()) {
					setFuelWithoutValidation(fuel.getCraftingRemainingItem());
				} else if (!fuel.isEmpty()) {
					fuel.shrink(1);
					setFuel(fuel);
					if (fuel.isEmpty()) {
						setFuel(fuel.getCraftingRemainingItem());
					}
				}
			}
		}
	}

protected boolean canSmelt(Recipe<?> cookingRecipe, Level level) {
		if (getCookInput().isEmpty()) {
			return false;
		}
		ItemStack recipeOutput = cookingRecipe.getResultItem(level.registryAccess());
		if (recipeOutput.isEmpty()) {
			return false;
		} else {
			ItemStack output = getCookOutput();
			if (output.isEmpty()) {
				return true;
			} else if (output.getItem() != recipeOutput.getItem()) {
				return false;
			} else if (output.getCount() + recipeOutput.getCount() <= 99 && output.getCount() + recipeOutput.getCount() <= output.getMaxStackSize()) {
				return true;
			} else {
				return output.getCount() + recipeOutput.getCount() <= recipeOutput.getMaxStackSize();
			}
		}
	}

@Override
	public void tick(@Nullable Entity entity, Level level, BlockPos pos) {
		if (isInCooldown(level)) {
			return;
		}

		if (!cookingLogic.tick(level)) {
			setCooldown(level, NOTHING_TO_DO_COOLDOWN);
		}

		boolean isBurning = cookingLogic.isBurning(level);
		RenderInfo renderInfo = storageWrapper.getRenderInfo();
		if (renderInfo.getUpgradeRenderData(CookingUpgradeRenderData.TYPE).map(CookingUpgradeRenderData::isBurning).orElse(false) != isBurning) {
			if (isBurning) {
				renderInfo.setUpgradeRenderData(CookingUpgradeRenderData.TYPE, new CookingUpgradeRenderData(true));
			} else {
				renderInfo.removeUpgradeRenderData(CookingUpgradeRenderData.TYPE);
			}
		}
	}

@Override
	public void setEnabled(boolean enabled) {
		if (!enabled) {
			pauseAndRemoveRenderInfo();
		}
		super.setEnabled(enabled);
	}

@Override
	public void onBeforeRemoved() {
		pauseAndRemoveRenderInfo();
	}

private void pauseAndRemoveRenderInfo() {
		cookingLogic.pause();
		RenderInfo renderInfo = storageWrapper.getRenderInfo();
		renderInfo.removeUpgradeRenderData(CookingUpgradeRenderData.TYPE);
	}
